def parse_bank():
    bank = {}
    for n, raw in enumerate(BANK_ROWS.strip().splitlines(), 1):
        values = tuple(part.strip() for part in raw.split("|"))
        if len(values) != len(FIELDS):
            raise ValueError(f"Year2 activity row {n}: wrong field count")
        item = dict(zip(FIELDS, values))
        sp = item.pop("sp")
        if sp in bank or any(not value for value in item.values()):
            raise ValueError(f"Duplicate or incomplete Year2 science SP {sp}")
        bank[sp] = item
    if len(bank) != 51:
        raise ValueError(f"Expected 51 distinct Year2 science plans: {len(bank)}")
    return bank

BANK = parse_bank()
